WITH base AS (SELECT * FROM subscriptions WHERE status IN ('CANCELLED', 'PAUSED')), subscriptions_stats AS (SELECT plan, QUARTER(end_date) AS end_quarter, AVG(monthly_fee) AS avg_monthly_fee, MIN(monthly_fee) AS min_monthly_fee FROM base GROUP BY plan, QUARTER(end_date)) SELECT plan, end_quarter, min_monthly_fee FROM subscriptions_stats ORDER BY end_quarter DESC, plan DESC LIMIT 10;
